package driver

import (
	"context"
	"fmt"
	"net/http"
	"os"
	"os/signal"
	"sync"
	"syscall"
	"time"

	"github.com/IBM/sarama"
	"github.com/signadot/hotrod/pkg/kafka"
	"github.com/signadot/hotrod/pkg/log"
	"github.com/signadot/hotrod/pkg/tracing"
	"go.uber.org/zap"
)

type Processor struct {
	logger log.Factory
}

func NewProcessor(logger log.Factory) *Processor {
	return &Processor{
		logger: logger,
	}
}

// Run starts the Driver server
func (p *Processor) Run() error {
	ctx, cancel := context.WithCancel(context.Background())

	p.logger.For(ctx).Info("Starting a new consumer")

	// get a tracer provider for the driver
	tracerProvider := tracing.InitOTEL("driver", p.logger)

	// create a consumer handler
	consumer := newConsumer(ctx, tracerProvider, p.logger)

	// create a new tracer provider for kafka
	kafkaTracerProvider := tracing.InitOTEL("kafka", p.logger)

	var (
		consumerGroup sarama.ConsumerGroup
		handler       sarama.ConsumerGroupHandler
		err           error
	)
	ticker := time.NewTicker(time.Second / 2)
	defer ticker.Stop()
	for {
		// create a consumer group
		consumerGroup, handler, err = kafka.GetConsumerGroup(
			"hotrod-driver", "driver", kafkaTracerProvider, consumer)
		if err == nil {
			break
		}
		select {
		case <-ctx.Done():
			cancel()
			return fmt.Errorf("error creating consumer group client: %v", err)
		case <-ticker.C:
			p.logger.For(ctx).Error("error creating consumer group client", zap.Error(err))
			p.logger.For(ctx).Info("retrying")
		}
	}

	wg := &sync.WaitGroup{}
	wg.Add(1)
	go func() {
		defer wg.Done()
		for {
			// `Consume` should be called inside an infinite loop, when a
			// server-side rebalance happens, the consumer session will need to be
			// recreated to get the new claims
			err := consumerGroup.Consume(ctx, []string{kafka.DispatchDriverTopic}, handler)
			if err != nil {
				p.logger.For(ctx).Error("Error from consumer", zap.Error(err))
			}
			// check if context was cancelled, signaling that the consumer should stop
			if ctx.Err() != nil {
				return
			}
			consumer.ready = make(chan bool)
		}
	}()

	<-consumer.ready // Await till the consumer has been set up
	p.logger.For(ctx).Info("Consumer up and running!")
	http.Handle("/healthz", http.HandlerFunc(func(resp http.ResponseWriter, req *http.Request) {
		p.logger.For(ctx).Info("handling /healthz")
		resp.Write([]byte("ok"))
	}))
	go http.ListenAndServe(":8082", http.DefaultServeMux)

	sigterm := make(chan os.Signal, 1)
	signal.Notify(sigterm, syscall.SIGINT, syscall.SIGTERM)

	keepRunning := true
	for keepRunning {
		select {
		case <-ctx.Done():
			p.logger.For(ctx).Info("terminating: context cancelled")
			keepRunning = false
		case <-sigterm:
			p.logger.For(ctx).Info("terminating: via signal")
			keepRunning = false
		}
	}
	cancel()
	wg.Wait()
	if err := consumerGroup.Close(); err != nil {
		p.logger.For(ctx).Error("could not close kafka consumer group", zap.Error(err))
	}
	return nil
}
package driver

import (
	"context"
	"errors"
	"math"
	"sync"
	"time"

	"github.com/signadot/hotrod/services/location"
	"go.opentelemetry.io/otel/codes"
	"go.opentelemetry.io/otel/trace"
	"go.uber.org/zap"

	"github.com/signadot/hotrod/pkg/config"
	"github.com/signadot/hotrod/pkg/log"
	"github.com/signadot/hotrod/pkg/pool"
	"github.com/signadot/hotrod/services/route"
)

type bestETA struct {
	tracer trace.Tracer
	route  route.Interface
	pool   *pool.Pool
	logger log.Factory
}

// Response contains ETA for a trip.
type Response struct {
	DriverID string
	ETA      time.Duration
}

func newBestETA(tracerProvider trace.TracerProvider, tracer trace.Tracer, logger log.Factory) *bestETA {
	return &bestETA{
		tracer: tracer,
		route:  route.NewClient(tracerProvider, logger, config.GetRouteAddr()),
		pool:   pool.New(config.GetDriverWorkerPoolSize()),
		logger: logger,
	}
}

func (eta *bestETA) Get(ctx context.Context, dispatchReq *DispatchRequest,
	drivers []*Driver) (*Response, error) {
	ctx, span := eta.tracer.Start(ctx, "CalculateBestRoute", trace.WithSpanKind(trace.SpanKindClient))
	defer span.End()

	// get all routes from the drivers to the pick up location
	results := eta.getRoutes(ctx, dispatchReq.PickupLocation, drivers)
	eta.logger.For(ctx).Info("Found routes", zap.Any("routes", results))

	// search the one with the best ETA
	resp := &Response{ETA: math.MaxInt64}
	for _, result := range results {
		if result.err != nil {
			span.SetStatus(codes.Error, result.err.Error())
			return nil, result.err
		}
		if result.route.ETA < resp.ETA {
			resp.ETA = result.route.ETA
			resp.DriverID = result.driverID
		}
	}
	if resp.DriverID == "" {
		err := errors.New("no routes found")
		span.SetStatus(codes.Error, err.Error())
		return nil, err
	}

	eta.logger.For(ctx).Info("Dispatch successful",
		zap.String("driverID", resp.DriverID),
		zap.String("eta", resp.ETA.String()),
	)
	return resp, nil
}

type routeResult struct {
	driverID string
	route    *route.Route
	err      error
}

// getRoutes calls Route service for each pick location, driver location pair
func (eta *bestETA) getRoutes(ctx context.Context, pickupLoc *location.Location,
	drivers []*Driver) []routeResult {
	results := make([]routeResult, 0, len(drivers))
	wg := sync.WaitGroup{}
	routesLock := sync.Mutex{}

	for _, dd := range drivers {
		wg.Add(1)
		driver := dd // capture loop var
		// Use worker pool to (potentially) execute requests in parallel
		eta.pool.Execute(func() {
			route, err := eta.route.FindRoute(ctx, driver.Coordinates, pickupLoc.Coordinates)
			routesLock.Lock()
			results = append(results, routeResult{
				driverID: driver.DriverID,
				route:    route,
				err:      err,
			})
			routesLock.Unlock()
			wg.Done()
		})
	}
	wg.Wait()
	return results
}
