import {Log, LogEntry} from "./useLogs.tsx";
import {useEffect, useState} from "react";
import { faker } from "@faker-js/faker";

export const useGetRequestArrival = (logs: Log[]) => {
    const [driverArrival, setDriverArrival] = useState<number | undefined>();
    const [driverDetails, setDriverDetails] = useState({
        name: "",
        plate: "",
    });

    const parseDriverLogService = (entry: LogEntry) => {
        if (entry.service !== 'driver') return;

        // Allow for optional minus sign in front of the time
        const rawTimeMatch = entry.status.match(/-?\d+m\d+s|-?\d+m|-?\d+s/);

        if (!rawTimeMatch) return; // No substring that looks like time

        const rawTime = rawTimeMatch[0];

        /**
         * Possible cases (including optional negative sign):
         * - 3m
         * - 3m2s
         * - 2s
         * - -3m
         * - -3m2s
         * - -2s
         */
        const timeRegex = /^(-)?(?:(\d+)m)?(?:(\d+)s)?$/;
        const match = rawTime.match(timeRegex);

        if (!match) return;

        const isNegative = !!match[1];
        const minutes = parseInt(match[2] || '0', 10);
        const seconds = parseInt(match[3] || '0', 10);

        let totalSeconds = minutes * 60 + seconds;
        if (isNegative) {
            totalSeconds = -totalSeconds;
        }

        return totalSeconds;
    };

    useEffect(() => {
        if (logs.length === 0) return;

        const lastRequestDrive = logs[0];

        setDriverArrival(undefined);

        if (!lastRequestDrive) {
            setDriverArrival(undefined);
            return;
        }

        const driverEntries = lastRequestDrive.entries.filter((e) => e.service === 'driver');
        const parsedTime = driverEntries
            .map((e) => parseDriverLogService(e))
            .find((e) => e !== undefined);

        const plate = driverEntries.map(e => {
            return e.status.match(/Driver\s+(.*?)\s+arriving/)
        }).find(e => e !== null);

        setDriverDetails({
            name: faker.person.fullName(),
            plate: plate && plate.length > 1 ? plate[1] : "Unknown",
        });
        setDriverArrival(parsedTime);
    }, [logs]);


    return {
        driverArrival,
        driverDetails,
    };
};
import {useState} from "react";
import {Location} from "../types/location.ts";


export type Log = {
    requestID: number,
    entries: LogEntry[],
    pickupLocation: Location,
    dropoffLocation: Location,
}

export type LogEntry = {
    messageType: 'error' | 'info',
    date: Date,
    service: string,
    status: string,
    sandboxName?: string,
}

export const useLogs = () => {
    const [logs, setLogs] = useState<Log[]>([]);

    const addNewLog = (pickupLocation: Location, dropoffLocation: Location, requestID: number, log: LogEntry) => {
        setLogs(prev => [{ pickupLocation, dropoffLocation, requestID, entries: [log]}, ...prev])
    }

    const addEntry = (requestID: number, body: Omit<LogEntry, "messageType">, messageType: LogEntry['messageType']): boolean => {
        let updated = false;
        setLogs(prevLogs => {
            return prevLogs.map(log => {
                if (log.requestID === requestID) {
                    updated = true;
                    return {
                        ...log,
                        entries: [...log.entries, {...body, messageType}],
                    };
                }
                return log;
            });
        });
        return updated;
    };

    const addErrorEntry = (requestID: number, body: Omit<LogEntry, "messageType">) => {
        return addEntry(requestID, body, 'error');
    };

    const addInformationEntry = (requestID: number, body: Omit<LogEntry, "messageType">) => {
        return addEntry(requestID, body, 'info');
    };


    return {
        addErrorEntry,
        addInformationEntry,
        addNewLog,
        logs
    }
}import React, {createContext, useContext, ReactNode, useRef} from 'react';

type SessionContextType = {
    sessionID: number | undefined;
    getLastRequestID: () => number;
}
const SessionContext = createContext<SessionContextType>({} as SessionContextType);

interface SessionProviderProps {
    children: ReactNode;
}

const createSessionID = () => {
    return Math.round(Math.random() * 10000);
}

export const SessionProvider: React.FC<SessionProviderProps> = ({ children }) => {
    const sessionIDRef = useRef(createSessionID());
    const lastRequestIDRef = useRef(1);

    const getLastRequestID = () => {
        const current = lastRequestIDRef.current;

        lastRequestIDRef.current += 1;
        return current;
    }

    return (
        <SessionContext.Provider value={{
            sessionID: sessionIDRef.current,
            getLastRequestID
        }}>
            {children}
        </SessionContext.Provider>
    );
};

export const useSession = () => {
    const context = useContext(SessionContext);
    if (context === undefined) {
        throw new Error('useSession must be used within a SessionProvider');
    }
    return context;
};
