// isMissingTable reports whether err is MySQL's "Table doesn't exist".
func isMissingTable(err error) bool {
	mysqlErr, ok := err.(*mysql.MySQLError)
	return ok && mysqlErr.Number == 1146
}

// withRideHistoryTable runs fn, and re-runs it once after creating the
// ride_history table if the first attempt failed because it doesn't exist.
func (d *database) withRideHistoryTable(fn func() error) error {
	err := fn()
	if err == nil || !isMissingTable(err) {
		return err
	}
	if err := d.setupRideHistory(); err != nil {
		return err
	}
	return fn()
}

// ListRideHistory returns the most recent rides (newest first, at most limit)
// and the total number of stored rides.
func (d *database) ListRideHistory(ctx context.Context, limit int) (*RideHistoryList, error) {
	d.logger.For(ctx).Info("Loading ride history", zap.Int("limit", limit))

	_, span := d.tracer.Start(ctx, "SQL SELECT", trace.WithSpanKind(trace.SpanKindClient))
	span.SetAttributes(
		semconv.PeerServiceKey.String("mysql"),
		attribute.
			Key("sql.query").
			String("SELECT ... FROM ride_history ORDER BY id DESC LIMIT ?"),
	)
	defer span.End()

	list := &RideHistoryList{Rides: []RideHistoryEntry{}}
	err := d.withRideHistoryTable(func() error {
		list.Rides = list.Rides[:0]
		if err := d.db.QueryRowContext(ctx, "SELECT COUNT(*) FROM ride_history").Scan(&list.Total); err != nil {
			return err
		}
		rows, err := d.db.QueryContext(ctx, `SELECT id, pickup_location, dropoff_location, request_time,
			driver_plate, fare FROM ride_history ORDER BY id DESC LIMIT ?`, limit)
		if err != nil {
			return err
		}
		defer rows.Close()
		for rows.Next() {
			var r RideHistoryEntry
			if err := rows.Scan(&r.ID, &r.PickupLocation, &r.DropoffLocation, &r.RequestTime,
				&r.DriverPlate, &r.Fare); err != nil {
				return err
			}
			list.Rides = append(list.Rides, r)
		}
		return rows.Err()
	})
	if err != nil {
		return nil, err
	}
	return list, nil
}

// CreateRideHistory stores a new ride and returns it with its ID populated.
func (d *database) CreateRideHistory(ctx context.Context, ride *RideHistoryEntry) (*RideHistoryEntry, error) {
	d.logger.For(ctx).Info("Creating ride history entry",
		zap.String("pickup", ride.PickupLocation), zap.String("dropoff", ride.DropoffLocation))

	var id int64
	err := d.withRideHistoryTable(func() error {
		res, err := d.db.ExecContext(ctx, `INSERT INTO ride_history
			(pickup_location, dropoff_location, request_time, driver_plate, fare)
			VALUES (?, ?, ?, ?, ?)`,
			ride.PickupLocation, ride.DropoffLocation, ride.RequestTime, ride.DriverPlate, ride.Fare)
		if err != nil {
			return err
		}
		id, err = res.LastInsertId()
		return err
	})
	if err != nil {
		return nil, err
	}
	created := *ride
	created.ID = id
	return &created, nil
}

// UpdateRideHistory sets the driver plate and fare of a ride.
func (d *database) UpdateRideHistory(ctx context.Context, update *RideHistoryUpdate) error {
	d.logger.For(ctx).Info("Updating ride history entry", zap.Int64("id", update.ID),
		zap.String("plate", update.DriverPlate), zap.Float64("fare", update.Fare))

	return d.withRideHistoryTable(func() error {
		res, err := d.db.ExecContext(ctx, "UPDATE ride_history SET driver_plate = ?, fare = ? WHERE id = ?",
			update.DriverPlate, update.Fare, update.ID)
		if err != nil {
			return err
		}
		n, err := res.RowsAffected()
		if err != nil {
			return err
		}
		if n > 0 {
			return nil
		}
		// MySQL reports 0 affected rows when the values didn't change, so
		// tell "unchanged" apart from "missing".
		var exists bool
		err = d.db.QueryRowContext(ctx, "SELECT EXISTS(SELECT 1 FROM ride_history WHERE id = ?)", update.ID).Scan(&exists)
		if err != nil {
			return err
		}
		if !exists {
			return ErrRideNotFound
		}
		return nil
	})
}

